32	    },
33	    (e: unknown) => e,
34	  );
35	  expect(error).toBeInstanceOf(PaymentsApiError);
36	  const apiError = error as PaymentsApiError;
37	  expect(apiError.status).toBe(expected.status);
38	  expect(apiError.code).toBe(expected.code);
39	  if (expected.message !== undefined) {
40	    expect(apiError.message).toBe(expected.message);
41	  }
42	}
